def source(text, rid="target", version=1):
    return {"id": rid, "text": text, "owner": "user-a", "version": version}


def gold(record):
    return {"record_id": record["id"], "version": record["version"], "start": 0,
            "end": len(record["text"]), "quote": record["text"]}


